namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A timeless Neapolitan pizza with fresh mozzarella, basil, and tomato sauce.",
            Ingredients = ["1 pizza dough ball", "1/2 cup San Marzano tomato sauce", "8 oz fresh mozzarella", "Fresh basil leaves", "2 tbsp olive oil", "Salt to taste"],
            Steps = ["Preheat oven to 500°F with a pizza stone.", "Stretch dough into a 12-inch round.", "Spread tomato sauce evenly, leaving a 1-inch border.", "Tear mozzarella and distribute over sauce.", "Bake for 8-10 minutes until crust is golden.", "Top with fresh basil and drizzle with olive oil."],
            TotalRatings = 12, RatingSum = 54
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato-based curry.",
            Ingredients = ["1.5 lbs chicken breast, cubed", "1 cup yogurt", "2 tbsp garam masala", "1 can crushed tomatoes", "1 cup heavy cream", "1 onion, diced", "3 cloves garlic", "1 inch ginger, grated"],
            Steps = ["Marinate chicken in yogurt and half the spices for 1 hour.", "Grill or pan-sear chicken until charred.", "Sauté onion, garlic, and ginger until soft.", "Add tomatoes and remaining spices; simmer 15 minutes.", "Stir in cream and add chicken.", "Simmer 10 minutes and serve with basmati rice."],
            TotalRatings = 8, RatingSum = 38
        },
        new()
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Classic Roman pasta with eggs, pecorino cheese, guanciale, and black pepper.",
            Ingredients = ["1 lb spaghetti", "6 oz guanciale or pancetta", "4 large egg yolks", "1 cup grated Pecorino Romano", "Freshly cracked black pepper", "Salt for pasta water"],
            Steps = ["Cook spaghetti in salted boiling water until al dente.", "Crisp guanciale in a skillet over medium heat.", "Whisk egg yolks with Pecorino and pepper.", "Drain pasta, reserving 1 cup pasta water.", "Toss hot pasta with guanciale off heat.", "Add egg mixture, tossing quickly; add pasta water to reach desired consistency."],
            TotalRatings = 15, RatingSum = 70
        },
        new()
        {
            Id = 4, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
            Ingredients = ["1 lb ground beef", "1 packet taco seasoning", "8 small tortillas", "1 cup shredded lettuce", "1 cup diced tomatoes", "1/2 cup shredded cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet over medium-high heat.", "Drain fat and add taco seasoning with 1/2 cup water.", "Simmer until sauce thickens, about 5 minutes.", "Warm tortillas in a dry skillet.", "Fill tortillas with beef and desired toppings.", "Serve immediately with salsa and sour cream."],
            TotalRatings = 10, RatingSum = 42
        },
        new()
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and a tangy tamarind sauce.",
            Ingredients = ["8 oz rice noodles", "1/2 lb shrimp, peeled", "2 eggs", "1/4 cup tamarind paste", "2 tbsp fish sauce", "1 tbsp sugar", "Bean sprouts", "Crushed peanuts", "Lime wedges"],
            Steps = ["Soak rice noodles in warm water for 30 minutes; drain.", "Mix tamarind paste, fish sauce, and sugar for the sauce.", "Stir-fry shrimp until pink; set aside.", "Scramble eggs in the same wok.", "Add noodles and sauce; toss until coated.", "Return shrimp, add bean sprouts, and top with peanuts and lime."],
            TotalRatings = 6, RatingSum = 27
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh avocado dip with lime, cilantro, and a kick of jalapeño.",
            Ingredients = ["3 ripe avocados", "1 lime, juiced", "1/4 cup cilantro, chopped", "1/2 jalapeño, minced", "1/4 red onion, diced", "Salt to taste"],
            Steps = ["Halve avocados and remove pits.", "Scoop flesh into a bowl and mash with a fork.", "Add lime juice, cilantro, jalapeño, and onion.", "Season with salt and mix gently.", "Serve immediately with tortilla chips."],
            TotalRatings = 9, RatingSum = 40
        },
        new()
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Description = "Aromatic coconut-based curry with vegetables and your choice of protein.",
            Ingredients = ["1 can coconut milk", "3 tbsp green curry paste", "1 lb chicken or tofu", "1 cup bamboo shoots", "1 bell pepper, sliced", "Thai basil leaves", "1 tbsp fish sauce", "1 tsp sugar"],
            Steps = ["Heat coconut cream (thick part) in a pot; stir in curry paste.", "Add protein and cook until done.", "Pour in remaining coconut milk.", "Add bamboo shoots and bell pepper; simmer 10 minutes.", "Season with fish sauce and sugar.", "Garnish with Thai basil and serve over jasmine rice."],
            TotalRatings = 5, RatingSum = 22
        },
        new()
        {
            Id = 8, Title = "Palak Paneer", Category = "Indian",
            Description = "Cubes of paneer cheese in a smooth, spiced spinach sauce.",
            Ingredients = ["10 oz fresh spinach", "8 oz paneer, cubed", "1 onion, diced", "2 cloves garlic", "1 inch ginger", "1 tsp cumin", "1/2 tsp garam masala", "1/4 cup cream"],
            Steps = ["Blanch spinach in boiling water for 2 minutes; transfer to ice water.", "Blend spinach into a smooth purée.", "Sauté onion, garlic, and ginger with cumin.", "Add spinach purée and simmer 5 minutes.", "Pan-fry paneer cubes until golden.", "Add paneer to spinach sauce, stir in cream and garam masala."],
            TotalRatings = 7, RatingSum = 31
        }
    ];

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public List<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Description = $"A community-submitted {submission.Category} recipe.",
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        });
    }
}

